// 1바이트씩 — 2,070 ms
try (InputStream in = new FileInputStream(src); OutputStream out = new FileOutputStream(dst)) {
    int b;
    while ((b = in.read()) != -1) out.write(b);
}

// 8KB 버퍼 — 1 ms
try (InputStream in = new FileInputStream(src); OutputStream out = new FileOutputStream(dst)) {
    byte[] buf = new byte[8192];
    int r;
    while ((r = in.read(buf)) != -1) out.write(buf, 0, r);
}
